import re

def clean_num(text):
    if text is None:
        return None
    text = text.strip().replace(',', '').replace('$', '').replace('€', '').replace('£', '').replace(' ', '')
    if not text or text in ['-', '—', 'null', 'n/a', 'None']:
        return None
    if text.startswith('(') and text.endswith(')'):
        text = '-' + text[1:-1]
    try:
        if text.endswith('%'):
            return float(text[:-1]) / 100.0
        return float(text)
    except ValueError:
        return None

def get_year(text):
    if not text:
        return None
    match = re.search(r'\b(20\d{2})\b', text)
    return float(match.group(1)) if match else None

def get_scale(text):
    if not text:
        return 1.0
    t = text.lower()
    if 'billion' in t: return 1e9
    if 'million' in t: return 1e6
    if 'thousand' in t: return 1e3
    return 1.0

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def scope_nodes(doc, scope_node):
    return [n for n in doc["nodes"] if n.get("parent_id") == scope_node.get("node_id")]

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: cell for j, cell in enumerate(row) if j < len(cols)}) for i, row in enumerate(rows)]

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    ents = {}
    for node in scope_nodes(doc, scope_node):
        if node['kind'] == 'table':
            rows = table_rows(node)
            cols = node['table']['columns']
            if not cols: continue
            col0 = cols[0]
            for i, row in rows:
                name = row.get(col0)
                if name and name.strip() and not any(x in name.lower() for x in ['total', 'balance', 'consolidated', 'beginning', 'ending']):
                    ents[name] = name
    return [{"id": k, "description": v} for k, v in ents.items()]

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    years = []
    for node in scope_nodes(doc, scope_node):
        if node['kind'] == 'table':
            for col in node['table']['columns']:
                y = get_year(col)
                if y: years.append(y)
            for row in node['table']['rows']:
                for cell in row:
                    y = get_year(cell)
                    if y: years.append(y)
        elif node['kind'] == 'list':
            for line in node.get('lines', []):
                y = get_year(line)
                if y: years.append(y)
        elif node['kind'] == 'text':
            y = get_year(node.get('text', ''))
            if y: years.append(y)
    return max(years) if years else None

